// ── KMP: Build Failure Function (lps array) — O(m) ─────────────
function buildLPS(pattern) {
  const m = pattern.length;
  const lps = new Array(m).fill(0);
  // lps[0] is always 0 — no proper prefix for a single character
  let len = 0; // length of the current longest prefix-suffix
  let i = 1;

  while (i < m) {
    if (pattern[i] === pattern[len]) {
      // Case 1: extend the current prefix-suffix
      lps[i] = ++len;
      i++;
    } else if (len > 0) {
      // Case 2: fall back to next shorter prefix-suffix
      // Do NOT increment i — try again with shorter prefix
      len = lps[len - 1];
    } else {
      // Case 3: no prefix-suffix possible at position i
      lps[i] = 0;
      i++;
    }
  }
  return lps;
}

// ── KMP: Search Phase — O(n) ───────────────────────────────────
function kmpSearch(text, pattern) {
  const n = text.length, m = pattern.length;
  if (m === 0) return [];
  const lps = buildLPS(pattern);
  const matches = [];
  let i = 0; // text index — ONLY moves forward
  let j = 0; // pattern index — can reset via lps

  while (i < n) {
    if (text[i] === pattern[j]) {
      i++;
      j++;
    }
    if (j === m) {
      // Full match found at text index (i - j)
      matches.push(i - j);
      // Use lps to continue searching (handles overlapping matches)
      j = lps[j - 1];
    } else if (i < n && text[i] !== pattern[j]) {
      if (j > 0) {
        j = lps[j - 1]; // fall back without moving i
      } else {
        i++; // no prefix to fall back to, advance text
      }
    }
  }
  return matches;
}

// ── Worked Example ──────────────────────────────────────────────
const text = "ABABDABACDABABCABAB";
const pattern = "ABABCABAB";

const lps = buildLPS(pattern);
console.log("LPS array:", lps);
// pattern: A B A B C A B A B
// lps:   [ 0,0,1,2,0,1,2,3,4 ]
// lps[8]=4 means 'ABABCABAB' has 'ABAB' as longest prefix=suffix

const result = kmpSearch(text, pattern);
console.log("Matches at indices:", result);
// Matches at indices: [10]
// text[10..18] = 'ABABCABAB' — verified!

// Test overlapping matches:
console.log(kmpSearch("AAAA", "AA")); // [0, 1, 2]
// At index 0: AA matches
// After match, j = lps[1] = 1 (not 0!), so next search starts
// with one 'A' already matched — correctly finds overlap at index 1

// ── Rabin-Karp Rolling Hash — O(n+m) expected ─────────────────
const BASE = 131;            // > alphabet size of typical text; any odd base works
const MOD = 1_000_000_007;   // large prime
// Keep every intermediate value below 2^53 (Number.MAX_SAFE_INTEGER):
// hash < 1e9 and code < 65,537, so hash * BASE and code * highPow stay < 2^53.
const code = (s, k) => s.charCodeAt(k) + 1; // UTF-16 unit + 1, never 0

function rabinKarp(text, pattern) {
  const n = text.length, m = pattern.length;
  const matches = [];
  if (m === 0 || m > n) return matches;

  // Precompute BASE^(m-1) mod MOD — the weight of the leftmost character
  let highPow = 1;
  for (let k = 0; k < m - 1; k++) highPow = (highPow * BASE) % MOD;

  // Initial hashes of the pattern and the first window
  let patHash = 0, winHash = 0;
  for (let k = 0; k < m; k++) {
    patHash = (patHash * BASE + code(pattern, k)) % MOD;
    winHash = (winHash * BASE + code(text, k)) % MOD;
  }

  for (let i = 0; i <= n - m; i++) {
    // Hash match is necessary, not sufficient: verify to rule out collisions
    if (winHash === patHash && text.startsWith(pattern, i)) matches.push(i);

    if (i < n - m) {
      // Remove text[i] (weight BASE^(m-1)); + MOD keeps the value non-negative
      winHash = (winHash - (code(text, i) * highPow) % MOD + MOD) % MOD;
      // Shift left one position and add text[i + m]
      winHash = (winHash * BASE + code(text, i + m)) % MOD;
    }
  }
  return matches;
}

console.log(rabinKarp("abcababcabc", "abc")); // [0, 5, 8]
console.log(rabinKarp("aaaaaa", "aa"));       // [0, 1, 2, 3, 4] — overlaps
console.log(rabinKarp("Hello World", "World")); // [6] — any characters

// ── Multi-pattern: k patterns of the same length m, one pass ──
function rabinKarpMulti(text, patterns) {
  const m = patterns[0].length;
  if (m === 0 || patterns.some(p => p.length !== m)) throw new Error('equal, non-empty lengths');
  const hashOf = (s, from) => {
    let h = 0;
    for (let k = from; k < from + m; k++) h = (h * BASE + code(s, k)) % MOD;
    return h;
  };
  const byHash = new Map();                 // hash -> patterns (several may collide)
  for (const p of patterns) {
    const h = hashOf(p, 0);
    if (!byHash.has(h)) byHash.set(h, []);
    byHash.get(h).push(p);
  }
  let highPow = 1;
  for (let k = 0; k < m - 1; k++) highPow = (highPow * BASE) % MOD;

  const found = [];
  if (text.length < m) return found;
  let h = hashOf(text, 0);
  for (let i = 0; i + m <= text.length; i++) {
    for (const p of byHash.get(h) ?? []) {   // O(1) expected lookup
      if (text.startsWith(p, i)) found.push([i, p]);
    }
    if (i + m < text.length) {
      h = (h - (code(text, i) * highPow) % MOD + MOD) % MOD;
      h = (h * BASE + code(text, i + m)) % MOD;
    }
  }
  return found;
}
console.log(rabinKarpMulti("the cat sat on the mat", ["cat", "mat", "dog"]));
// [[4, 'cat'], [19, 'mat']]
